def can_reach_from_any_2_without_crossing(pos, target_positions, start_positions):
    """Can we draw a path from any 2 to target without passing through another 2?"""
    r, c = pos

    # Try horizontal movement first
    for dc in [-1, 1]:
        can_cross = True
        step = dc
        current_c = c + step
        visited = set()

        while 0 <= current_c < 11 and can_cross:
            new_pos = (r, current_c)
            if new_pos == start_positions[0]:  # Check against ONE specific 2 as starting point
                pass  # Allow landing ON the source 2

            if new_pos in target_positions:
                can_cross = False
                break

            for sr, sc in start_positions:
                if new_pos == (sr, sc) and new_pos not in visited:
                    visited.add(new_pos)

            current_c += step

        if can_cross:
            return True

    # Try vertical
    for dr in [-1, 1]:
        can_cross = True
        step = dr
        current_r = r + step

        while 0 <= current_r < 11 and can_cross:
            new_pos = (current_r, c)

            for sr, sc in start_positions:
                if new_pos == (sr, sc) and new_pos not in visited:
                    continue

            if new_pos in target_positions:
                can_cross = False
                break

            current_r += step

        if can_cross:
            return True

    return False

